Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    long long x, y, n;
    cin >> x >> y >> n;
    long double ratio = (long double)x / (long double)y;
    pair<long long, long long> best_pair;
    long double smallest_diff = std::numeric_limits<long double>::max();

    for (long long denominator = 1; denominator <= n; ++denominator) {
        long double approximate = ratio * denominator;
        long long numerator_floor = (long long)approximate;
        long long numerator_ceil = numerator_floor + 1;

        long double diff_floor = fabs(ratio - (long double)numerator_floor / denominator);
        long double diff_ceil = fabs((long double)numerator_ceil / denominator - ratio);

        if (diff_floor < smallest_diff) {
            smallest_diff = diff_floor;
            best_pair = {numerator_floor, denominator};
        }
        if (diff_ceil < smallest_diff) {
            smallest_diff = diff_ceil;
            best_pair = {numerator_ceil, denominator};
        }
    }
    cout << best_pair.first << "/" << best_pair.second;
    return 0;
}
</original_code>
